//! `vsm_data.js`: a generated, read-only mirror of the plan in the schema `vsm_viewer.html`
//! reads (also in `resources/templates/vsm_data.template.js`), so agents and the user can
//! read the graph and the Future Horizon on disk with Foundry closed.
//!
//! Deterministic: the same plan gives the same bytes (struct field order, sorted lists, no
//! revision, no timestamps). Nothing ever reads it back into the plan.

use serde::Serialize;

use super::graph::Derived;
use super::PlanFile;

pub const FILE: &str = "vsm_data.js";

const HEADER: &str = "\
// vsm_data.js: GENERATED by Foundry from .foundry/plan.json. Do not edit: the next plan
// change overwrites this file. Change the plan in Foundry instead.
//
// Schema (read by vsm_viewer.html):
//   meta: { title, subtitle }
//   slices: [{
//     id, name,
//     order: 1 for slices with no dependencies, otherwise 1 + the longest chain below it;
//            slices with the same order can be built in parallel,
//     status: \"queued\" | \"in_progress\" | \"done\",
//     depends_on: [slice ids], delivers: [capabilities],
//     used_by: how many slices depend on this one,
//     resolved: [decisions made], open: [open questions],
//     workspace_access: true when an agent on this slice may also edit the root
//                       workspace files (package.json, the pnpm files, tsconfig.base.json,
//                       .gitignore, .npmrc)
//   }]
//   future_horizon: [{ id, label, anchored_to: slice id }]: deferred features. Don't build
//     interfaces that block them (AGENTS.md, Law 8).
";

#[derive(Serialize)]
struct VsmData<'a> {
    meta: Meta<'a>,
    slices: Vec<VsmSlice<'a>>,
    future_horizon: Vec<Horizon<'a>>,
}

#[derive(Serialize)]
struct Meta<'a> {
    title: &'a str,
    subtitle: &'a str,
}

#[derive(Serialize)]
struct VsmSlice<'a> {
    id: &'a str,
    name: &'a str,
    order: u32,
    status: super::SliceStatus,
    depends_on: Vec<&'a str>,
    delivers: &'a [String],
    used_by: u32,
    resolved: &'a [String],
    open: Vec<&'a str>,
    workspace_access: bool,
}

#[derive(Serialize)]
struct Horizon<'a> {
    id: &'a str,
    label: &'a str,
    anchored_to: &'a str,
}

pub fn render(plan: &PlanFile, derived: &Derived, title: &str, subtitle: &str) -> String {
    let mut slices: Vec<VsmSlice> = plan
        .slices
        .iter()
        .map(|s| {
            let mut depends_on: Vec<&str> = s.depends_on.iter().map(String::as_str).collect();
            depends_on.sort_unstable();
            depends_on.dedup();
            VsmSlice {
                id: &s.id,
                name: &s.name,
                order: derived.layer.get(&s.id).copied().unwrap_or(0) + 1,
                status: s.status,
                depends_on,
                delivers: &s.delivers,
                used_by: derived.used_by.get(&s.id).copied().unwrap_or(0),
                resolved: &s.decisions,
                open: s.open_questions.iter().map(|q| q.text.as_str()).collect(),
                workspace_access: s.workspace_access,
            }
        })
        .collect();
    slices.sort_by(|a, b| (a.order, a.name, a.id).cmp(&(b.order, b.name, b.id)));
    let mut future_horizon: Vec<Horizon> = plan
        .deferred
        .iter()
        .map(|d| Horizon {
            id: &d.id,
            label: &d.label,
            anchored_to: &d.anchored_to,
        })
        .collect();
    future_horizon.sort_by(|a, b| (a.label, a.id).cmp(&(b.label, b.id)));
    let data = VsmData {
        meta: Meta { title, subtitle },
        slices,
        future_horizon,
    };
    // Serializing plain structs of strings and numbers can't fail.
    let json = serde_json::to_string_pretty(&data).unwrap_or_else(|_| "{}".into());
    format!("{HEADER}\nconst VSM_DATA = {json};\n")
}
